$dir = "$scratch\elden-ring-xl\A8A21595-1D57-5C6B-9D6B-A4B1BD6C38D0.sdProfile\Profiles"
Get-ChildItem $dir -Directory | ForEach-Object {
  $f = Join-Path $_.FullName "manifest.json"
  $m = Get-Content $f | ConvertFrom-Json
  Write-Output "--- $($_.Name) ---"
  foreach ($c in $m.Controllers) {
    if ($c.Actions) {
      foreach ($p in $c.Actions.PSObject.Properties) {
        $a = $p.Value
        $settings = $a.Settings | ConvertTo-Json -Compress
        Write-Output "$($c.Type) $($p.Name): $($a.UUID) $settings"
      }
    } else {
      Write-Output "$($c.Type): (empty)"
    }
  }
}

